def get_lr(it, warmup_iters, lr_decay_iters, learning_rate, min_lr):
    """Warmup, Slow Linear Decay, Fast Cosine Cooldown (WSFC)."""
    if it < warmup_iters:
        return learning_rate * (it + 1) / (warmup_iters + 1)

    cooldown_start = int(lr_decay_iters * 0.8)
    mid_lr = learning_rate * 0.5

    if it < cooldown_start:
        ratio = (it - warmup_iters) / (cooldown_start - warmup_iters)
        return learning_rate - ratio * (learning_rate - mid_lr)

    if it > lr_decay_iters:
        return min_lr

    ratio = (it - cooldown_start) / (lr_decay_iters - cooldown_start)
    coeff = 0.5 * (1.0 + math.cos(math.pi * ratio))
    return min_lr + coeff * (mid_lr - min_lr)

